update pages set contenu = '{"gabarit":"editorial","chapeau":"Le préventif qui saute, le budget correctif qui explose, le service maintenance qui court après les pannes : ces articles s''attaquent à ces sujets un par un. Ils prolongent notre [guide maintenance industrielle](/ressources/) avec un format plus long : la définition, la méthode, l''exemple, et ce qu''en fait un technicien sur le terrain.","blocs":[]}'::jsonb where path = '/ressources/articles/';
update pages set contenu = jsonb_set(contenu, '{blocs}', (contenu->'blocs') || '[{"type":"citation","texte":"Chaque article est écrit par des équipes qui interviennent tous les jours en usine, chez plus de 120 clients. Pas de théorie hors sol : des méthodes qui tiennent en atelier comme en réunion."},{"type":"titre","niveau":2,"texte":"Choisir sa stratégie de maintenance","id":"choisir-sa-strategie-de-maintenance"},{"type":"paragraphe","texte":"Avant d''organiser, il faut trancher : réparer après la panne, ou l''anticiper ? Deux articles pour poser le curseur."},{"type":"liste","items":[{"accroche":"Arbitrer préventif contre correctif","texte":"L''article [maintenance préventive et corrective](/ressources/articles/preventive-ou-corrective/) compare les deux logiques et dit où placer chaque machine."},{"accroche":"Peser l''intérêt du prédictif","texte":"Le comparatif [maintenance prédictive ou corrective](/ressources/articles/predictive-ou-corrective/) chiffre quand la surveillance rapporte plus qu''elle ne coûte."}]},{"type":"titre","niveau":2,"texte":"Organiser et piloter son service","id":"organiser-et-piloter-son-service"},{"type":"paragraphe","texte":"Une maintenance qui subit se répare avec de la méthode, pas avec des heures supplémentaires. Ces guides structurent le quotidien."},{"type":"liste","items":[{"accroche":"Bâtir le référentiel","texte":"Le guide [plan de maintenance](/ressources/articles/plan-de-maintenance/) pose le document qui organise l''entretien de tout un parc, gamme par gamme."},{"accroche":"Cadencer les interventions","texte":"L''article [planning de maintenance](/ressources/articles/planification-maintenance/) lisse la charge sur l''année et hiérarchise les priorités."},{"accroche":"Monter le service","texte":"Le guide [comment organiser un service de maintenance](/ressources/articles/organiser-service-maintenance/) trace la structure, les rôles et les rituels qui tiennent."},{"accroche":"Gagner en efficacité","texte":"L''article [optimisation de la maintenance](/ressources/articles/optimiser-la-maintenance/) cible les points où l''on gagne du temps sans dégrader la fiabilité."},{"accroche":"Tracer et améliorer","texte":"Le guide [suivi de la maintenance](/ressources/articles/suivi-de-la-maintenance/) montre quels indicateurs suivre et comment les faire vivre."},{"accroche":"Impliquer la production","texte":"L''article [tpm maintenance](/ressources/articles/tpm/) fait de l''opérateur le premier capteur du parc, geste par geste."}]},{"type":"titre","niveau":2,"texte":"Digitaliser et chiffrer la maintenance","id":"digitaliser-et-chiffrer-la-maintenance"},{"type":"paragraphe","texte":"Un plan vit dans un outil, pas dans un classeur. Ces articles relient la donnée au budget."},{"type":"liste","items":[{"accroche":"Centraliser dans un outil","texte":"Le guide [gestion de maintenance assistée par ordinateur](/ressources/articles/gmao/) explique ce qu''une GMAO change vraiment au quotidien."},{"accroche":"Comprendre l''apport de l''IA","texte":"L''article [ia maintenance](/ressources/articles/ia-maintenance/) démêle le concret de la promesse sur le diagnostic assisté."},{"accroche":"Passer à la 4.0","texte":"Le guide [maintenance 4.0](/ressources/articles/maintenance-4-0/) pose les capteurs et les données par étapes, sans usine à gaz."},{"accroche":"Chiffrer l''immobilisation","texte":"L''article [coût d''un arrêt de production](/ressources/articles/cout-arret-de-production/) met un prix sur l''heure perdue, l''argument qui débloque un budget."}]},{"type":"citation","texte":"Un doute sur votre organisation, un indicateur qui dérive ? Nos techniciens font le diagnostic sur site : appelez le 04 78 33 72 05, un chargé d''affaires vous rappelle dans l''heure."}]'::jsonb) where path = '/ressources/articles/';
update pages set contenu = jsonb_set(contenu, '{blocs}', (contenu->'blocs') || '[{"type":"citation","texte":"À lire aussi : [Ressources : Fiches pratiques](/ressources/fiches-pratiques/)"},{"type":"citation","texte":"[Demander un diagnostic maintenance](/contact/)"}]'::jsonb) where path = '/ressources/articles/';
